function readCsv(file, callback) { 
    fs.readFile(file, 'utf-8', function (err, data) { 
        if (err) throw err; 
        var lines = data.split('\r\n'); 

        var result = lines.map(function (line) { 
            return line.split(','); 
        }); 

        callback(result); 
    }); 
} 

